extern "C" int strcmp(const char *, const char *);

class stringx {
protected:
  char *chars;
  void *my_buf;
public:
  const char *c_str() const { return chars; }
};

template<class T> struct my_allocator {};
template<class T, class Alloc = my_allocator<T> > struct vector {
  T *start;
  T *finish;
  T *end_of_storage;
};

class animation_interface {
public:
  struct s_t_s_t_r {
    bool operator()(const stringx& a, const stringx& b) const {
      return strcmp(a.c_str(), b.c_str()) < 0;
    }
  };
  struct anim_info {
    float percent;
    stringx anim;
    int damage;
    float recover_time;
    float recover_var;
    int flags;
  };
};

template<class T1, class T2> struct pair {
  T1 first;
  T2 second;
};
typedef vector<animation_interface::anim_info> anim_vector;
typedef pair<const stringx, anim_vector> value_type;

struct _Rb_tree_node_base {
  int color;
  _Rb_tree_node_base *parent;
  _Rb_tree_node_base *left;
  _Rb_tree_node_base *right;
};
struct node : _Rb_tree_node_base { value_type value_field; };

