iterator tree_insert(tree *self, _Rb_tree_node_base *x_, _Rb_tree_node_base *y_, const value_type& v) {
  node *x = (node *)x_;
  node *y = (node *)y_;
  node *z;
  if (y == (node *)self->_M_header || x != 0 || self->_M_key_compare(v.first, y->value_field.first)) {
    z = create_node(self, v);
    y->left = z;
    if (y == (node *)self->_M_header) {
      self->_M_header->parent = z;
      self->_M_header->right = z;
    } else if (y == (node *)self->_M_header->left)
      self->_M_header->left = z;
  } else {
    z = create_node(self, v);
    y->right = z;
    if (y == (node *)self->_M_header->right)
      self->_M_header->right = z;
  }
  z->parent = y;
  z->left = 0;
  z->right = 0;
  rebalance(z, self->_M_header->parent);
  ++self->_M_node_count;
  return iterator(z);
}
